def LNr(X): X=X-X.mean(1,keepdims=True); return X/X.std(1,keepdims=True)
def zsall(X): mu=X.mean(0); sd=X.std(0)+1e-6; return (X-mu)/sd/np.sqrt(X.shape[1])
def evalfeat(X, y, gammas=(0.2,0.4,0.8), lams=(0.001,0.003,0.01)):
    # LOO
    Z=zsall(X); sq=(Z**2).sum(1); D2=np.maximum(sq[:,None]+sq[None]-2*Z@Z.T,0); T=np.eye(8)[y]-1/8; loo={}
    for g in gammas:
        K=np.exp(-g*D2); w,V=np.linalg.eigh(K)
        for l in lams:
            f=w/(w+l); Hd=((V**2)*f[None]).sum(1); Yh=V@(f[:,None]*(V.T@T))
            loo[(g,l)]=(((Yh-Hd[:,None]*T)/(1-Hd[:,None])).argmax(1)==y).mean()
    # 5-fold 3 seeds (standardize per fold approx by global; fine)
    cv={}
    for s in (0,1,2):
        for te in folds(len(y),5,s,y):
            tr=np.setdiff1d(np.arange(len(y)),te)
            for g in gammas:
                K=np.exp(-g*D2); Ktr=K[np.ix_(tr,tr)]; w,V=np.linalg.eigh(Ktr); R=V.T@T[tr]
                for l in lams:
                    p=(K[np.ix_(te,tr)]@(V@(R/(w+l)[:,None]))).argmax(1); cv[(g,l)]=cv.get((g,l),0)+(p==y[te]).sum()
    cv={k:v/(3*len(y)) for k,v in cv.items()}
    return round(max(loo.values()),4), round(float(np.median(list(loo.values()))),4), round(max(cv.values()),4), round(float(np.median(list(cv.values()))),4)
